import{_ as t,o,c as a,ae as r}from"./chunks/framework.EHGTsUvI.js";const p=JSON.parse('{"title":"Sheep","description":"","frontmatter":{"title":"Sheep"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Animals/sheep.md","filePath":"Main/Main/GeneralKnowledge/Animals/sheep.md"}'),n={name:"Main/Main/GeneralKnowledge/Animals/sheep.md"};function i(s,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="sheep" tabindex="-1">Sheep <a class="header-anchor" href="#sheep" aria-label="Permalink to &quot;Sheep&quot;">​</a></h1><p>Sheep are a livestock animal that produce <strong>Wool</strong>. Wool can be collected by shearing sheep and processed using a <strong>Spindle Machine</strong> to create Wool Bundles, which can then be sold at AnimalCo.</p><h2 id="how-to-obtain" tabindex="-1">How to Obtain <a class="header-anchor" href="#how-to-obtain" aria-label="Permalink to &quot;How to Obtain&quot;">​</a></h2><p>Sheep can be purchased from <strong>AnimalCo</strong>.</p><p>To purchase sheep:</p><ol><li>Take a suitable animal trailer to AnimalCo.</li><li>Position the trailer in the marked animal purchase area.</li><li>Purchase the desired number of sheep.</li><li>The sheep will automatically be loaded into the trailer.</li><li>Transport them back to your farm.</li></ol><p>A trailer capable of transporting large animals is required.</p><h2 id="purchase-price" tabindex="-1">Purchase Price <a class="header-anchor" href="#purchase-price" aria-label="Permalink to &quot;Purchase Price&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Sheep</td><td>3,000 Coins each</td></tr><tr><td>Selling Price</td><td>1,500 Coins each</td></tr></tbody></table><p>Sheep cost <strong>3,000 Coins</strong> each when purchased from AnimalCo.</p><h2 id="housing-requirements" tabindex="-1">Housing Requirements <a class="header-anchor" href="#housing-requirements" aria-label="Permalink to &quot;Housing Requirements&quot;">​</a></h2><p>Sheep require a suitable fenced area where they can roam.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Details</th></tr></thead><tbody><tr><td>Fenced Area</td><td>Required</td></tr><tr><td>Feeder</td><td>Regular Feeder</td></tr><tr><td>Animal Food</td><td>Required</td></tr><tr><td>Barn</td><td>Not required</td></tr></tbody></table><p>Sheep use a <strong>Regular Feeder</strong> rather than a Chicken Feeder. They also need enough space to move around and access their food.</p><h2 id="food-requirements" tabindex="-1">Food Requirements <a class="header-anchor" href="#food-requirements" aria-label="Permalink to &quot;Food Requirements&quot;">​</a></h2><p>Sheep eat <strong>Animal Food</strong>.</p><p>Animal Food can be purchased from AnimalCo or produced using an <strong>Animal Food Factory</strong>.</p><p>To feed sheep, place a Regular Feeder in their fenced area and fill it with Animal Food.</p><blockquote><p><strong>Important:</strong> Sheep need to remain fed in order to continue producing Wool.</p></blockquote><h2 id="products-produced" tabindex="-1">Products Produced <a class="header-anchor" href="#products-produced" aria-label="Permalink to &quot;Products Produced&quot;">​</a></h2><p>Sheep produce <strong>Wool</strong>.</p><p>Wool can be collected by shearing sheep and then processed using a Spindle Machine to create Wool Bundles.</p><table tabindex="0"><thead><tr><th>Product</th><th>Details</th></tr></thead><tbody><tr><td>Wool</td><td>Collected by shearing Sheep</td></tr><tr><td>Wool Bundle</td><td>Produced using a Spindle Machine</td></tr><tr><td>Wool Bundle Use</td><td>Used in the Shirt Factory</td></tr></tbody></table><p>The current 2026 community guide lists Wool Bundles as requiring <strong>5 pieces of Wool</strong>.</p><h2 id="production-time" tabindex="-1">Production Time <a class="header-anchor" href="#production-time" aria-label="Permalink to &quot;Production Time&quot;">​</a></h2><p>A fixed Wool production time is <strong>not currently reliably documented</strong> in the available sources.</p><p>Wool production is tied to the sheep&#39;s wool growth cycle. Once Wool is available, the sheep can be sheared manually.</p><blockquote><p><strong>Note:</strong> A fixed production time should be added once confirmed in-game rather than using an unverified value.</p></blockquote><h2 id="selling-information" tabindex="-1">Selling Information <a class="header-anchor" href="#selling-information" aria-label="Permalink to &quot;Selling Information&quot;">​</a></h2><p>Sheep themselves can be sold for <strong>1,500 Coins</strong> each.</p><p>Wool is processed into <strong>Wool Bundles</strong>, which can be sold at the animal product selling area at <strong>AnimalCo</strong>.</p><p>Wool can also be used as an ingredient in the <strong>Shirt Factory</strong>, making sheep useful for textile production.</p><h2 id="required-license" tabindex="-1">Required License <a class="header-anchor" href="#required-license" aria-label="Permalink to &quot;Required License&quot;">​</a></h2><table tabindex="0"><thead><tr><th>License</th><th>Required</th></tr></thead><tbody><tr><td>Sheep License</td><td>Yes</td></tr></tbody></table><p>The <strong>Sheep License</strong> is required before Sheep can be purchased.</p><p>The Sheep License is unlocked through the <strong>Animals Goals</strong> progression at approximately <strong>7,200 XP</strong>.</p><h2 id="other-useful-information" tabindex="-1">Other Useful Information <a class="header-anchor" href="#other-useful-information" aria-label="Permalink to &quot;Other Useful Information&quot;">​</a></h2><ul><li>Sheep cost <strong>3,000 Coins</strong> each.</li><li>Sheep require a <strong>Sheep License</strong>.</li><li>Sheep require a <strong>fenced area, Regular Feeder and Animal Food</strong>.</li><li>Sheep can be manually sheared using <strong>Shears</strong> purchased from AnimalCo.</li><li>Wool can be processed into <strong>Wool Bundles</strong> using a Spindle Machine.</li><li>Wool Bundles can be sold at <strong>AnimalCo</strong>.</li><li>Wool is also used in the <strong>Shirt Factory</strong>.</li><li>A suitable animal trailer is required to transport Sheep from AnimalCo to your farm.</li><li>The default animal limit is <strong>32 animals per farm</strong>, increased to <strong>52</strong> with the More Animals game pass.</li><li>Keeping Sheep fed is important for maintaining Wool production.</li></ul>',38)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
